// Prompt strings for the Rust decomposed-PRD lifecycle — ported VERBATIM from
// the scaffold JS `task:` strings (body_a/body_b/noop/remediation/verification
// splice/ownership splice). Do not edit copy without updating the agents'
// structured-output expectations.
//
// Lives here rather than beside the lifecycle driver because it is the one part
// of that cluster with no dependencies at all: pure `&'static str` and one
// `format!`. Siting it in the crate the driver will eventually move into lets
// every caller name it by one absolute path instead of the four relative reach
// styles it accumulated in the binary (`super::`, `super::super::`, a glob
// re-export alias, and a second `#[path]` inclusion that needed
// `allow(clippy::duplicate_mod)`).

pub const HOST_PATCH_MANIFEST_SCHEMA_GROUNDING: &str = "The host-owned archon.workflow.patch_manifest.v1 schema contains only schema, run_id, stage_id, item_id, baseline_commit, patch_path, declared_target_files, changed_files, created_files, deleted_files, pre_hashes, post_hashes, verify_command, agent_artifact_path, and status. The only valid write-scope invariant is observed writes (changed_files plus created_files plus deleted_files) are a subset of declared_target_files. Declared files are not required to change, and empty observed writes are valid for idempotent_noop. Never require declared_target_files to be a subset of changed_files. provider_env_proof is run-scoped and must be resolved from workflow input or run evidence. source_item_id, canonical_task_ids, normalized_path, write_coordination_scope, and provider evidence are not patch-manifest fields and must never be required inside that manifest. Host-schema differences are verification-shape issues, never agent write-remediation work.";

pub fn ground_host_manifest_schema(task: &str) -> String {
    format!("{task} {HOST_PATCH_MANIFEST_SCHEMA_GROUNDING}")
}

pub const DISCOVERY_TASK: &str = "Run read-only discovery in parallel. Return structured summaries only: files read, commands run, task coverage, implementation gaps, artifact requirements, and risks. Do not accept implementation tasks from read-only work. Every deliverable contract carries a host-stamped artifact_status (resolved_path, exists, bytes, root) computed against projectArtifactRoot and targetRepositoryRoot at run start; treat it as the authoritative existence signal for declared artifacts. Never conclude a declared artifact is absent from globs or directory listings inside your checkout: agent worktrees are git checkouts and cannot contain gitignored or project-root files.";

pub const DISCOVERY_ITEM_PRD_TASK_REVIEW: &str = "Read the PRD, decomposed task files, implementation slice, and context files. Return structured requirements, dependency evidence, task coverage requirements, verification requirements, artifact requirements, and residual risks. Distinguish repository source paths from project artifact/data paths under projectArtifactRoot.";

pub const DISCOVERY_ITEM_REPOSITORY_AUDIT: &str = "Inspect the target repository for existing implementation relevant to taskText. Return concrete files read, existing evidence, missing work, test commands, and safety concerns. Do not modify files.";

pub const DISCOVERY_ITEM_ACCEPTANCE_AUDIT: &str = "Map every canonical task in taskUniverse to acceptance criteria, required artifacts, provider/data constraints, focused verification commands, and required_tools. When a TASK requires project MCP or other project-configured tooling, use exact configured tool names from projectArtifactRoot/.mcp.json in required_tools. Use governedLearningContext only as sanitized prior-run hints with evidence refs; verify every claim against current PRD/code. Artifact paths must be checked relative to projectArtifactRoot when they are project artifacts. Do not mark implementation tasks accepted from read-only evidence.";

pub const CANONICAL_INVENTORY_TASK: &str = "Using taskUniverse, discovery, and governedLearningContext, produce dependency-owned inventory items only for genuinely missing or provably no-op work. Treat learning context as advisory evidence references, not truth. Every item must include work_type and preserve required_tools discovered from the TASK/project MCP config. implementation items require item_id, canonical_task_ids, dependency_ids using canonical task IDs only, target_files, acceptance_criteria, focused_verification, and artifact_requirements. artifact_requirements is only for concrete project artifact paths; prose evidence expectations belong in expected_evidence and fix instructions belong in required_fix. target_files must be repo-owned implementation files under targetRepositoryRoot; task docs, context, progress, report, and artifact paths are evidence/artifact refs, not implementation write targets. A task whose only deliverables are project artifacts is still an implementation item: give it target_files [] with concrete artifact_requirements, exactly as artifact-only remediation does; never fabricate a repository path for it and never block the inventory over it. Split grouped items by dependency readiness: no dependency_id may overlap the same item's canonical_task_ids, and do not group tasks when one claimed task depends on another claimed task. Prerequisite tasks must be represented as implementation or verified_noop items. verified_noop items require item_id, canonical_task_ids, dependency_ids, acceptance_criteria, noop_proof, proof reference entries, and artifact_requirements, using [] only with evidence that no artifact/output is required. Do not emit an empty inventory unless every canonical task has concrete accepted/noop proof. Every deliverable contract carries a host-stamped artifact_status (resolved_path, exists, bytes, root) computed against projectArtifactRoot and targetRepositoryRoot at run start; treat it as the authoritative existence signal for declared artifacts. Never conclude a declared artifact is absent from globs or directory listings inside your checkout: agent worktrees are git checkouts and cannot contain gitignored or project-root files.";

pub const INVENTORY_SHAPE_REPAIR_TASK: &str = "Repair inventory shape only. Preserve taskUniverse canonical IDs and all existing schedulable fields. Return repaired implementation items with work_type, item_id, canonical_task_ids, dependency_ids, target_files, acceptance_criteria, focused_verification, and artifact_requirements. Return repaired verified_noop items with item_id, canonical_task_ids, dependency_ids, acceptance_criteria, noop_proof, noop_proof_refs/proof_references, and artifact_requirements, using [] only with evidence that no artifact/output is required. Do not replace detailed items with skeletons. Put crosscutting/support notes in repair_summary or evidence_refs, not inventory items.";

pub const TASK_UNIVERSE_RECONCILE_TASK: &str = "Reconcile inventory dependency IDs to canonical task IDs in taskUniverse. Return repaired items or evidence that dependencies are genuinely unresolved.";

pub const DEPENDENCY_GRAPH_REPAIR_TASK: &str = "Repair dependency graph defects before scheduling. Split grouped items by dependency readiness while preserving or restoring every schedulable field required by the contract. implementation items must include target_files, acceptance_criteria, focused_verification, and artifact_requirements. verified_noop items must include acceptance_criteria, noop_proof, noop_proof_refs/proof_references, and artifact_requirements. Add verified_noop prerequisite items only with concrete proof refs. Remove impossible internal dependency edges only with evidence, or return concrete unrecoverable graph evidence. No dependency_id may overlap the same item's canonical_task_ids. Put crosscutting verification/support notes in repair_summary or evidence_refs, not inventory items.";

pub const TARGET_FILE_DISCOVERY_TASK: &str = "Investigate missing or invalid target files from PRD/TASK files and repository evidence. Return repaired implementation items whose target_files are repo-owned implementation files under targetRepositoryRoot, or convert to verified_noop with concrete proof refs. Do not use task context/progress/report/artifact files as implementation target_files. A task whose only deliverables are project artifacts is repaired by returning it with target_files [] and its concrete artifact_requirements — that is a complete, valid repair, not a failure; never block the pass over such a task and never fabricate a repository path for it. Blocking is only for a code-producing task whose safe repo-owned targets genuinely cannot be inferred. Every deliverable contract carries a host-stamped artifact_status (resolved_path, exists, bytes, root) computed against projectArtifactRoot and targetRepositoryRoot at run start; treat it as the authoritative existence signal for declared artifacts. Never conclude a declared artifact is absent from globs or directory listings inside your checkout: agent worktrees are git checkouts and cannot contain gitignored or project-root files.";

pub const VERIFICATION_REQUIREMENTS_DISCOVERY_TASK: &str = "Investigate missing acceptance criteria or focused verification requirements. Return repaired items with focused_verification and acceptance_criteria or concrete evidence that requirements are unavailable.";

pub const ARTIFACT_REQUIREMENTS_DISCOVERY_TASK: &str = "Investigate artifact requirements from PRD/TASK files. Return repaired items with artifact_requirements containing concrete project artifact paths only, using an empty array only when no artifact is required and that no-op is evidenced. Put prose evidence expectations in expected_evidence, not artifact_requirements.";

pub const PROVIDER_ENVIRONMENT_DISCOVERY_TASK: &str = "Investigate provider/environment evidence without exposing secrets. Return repaired items with redacted env keys checked, commands_run summaries, and provider evidence or concrete external-unavailable evidence.";

pub const EVIDENCE_REPAIR_TASK: &str = "Repair missing verified no-op evidence fields. Return repaired items with noop_proof and noop_proof_refs/proof_references tied to PRD/TASK criteria, or concrete evidence that no safe no-op proof exists.";

pub const BLOCKED_MALFORMED_INVENTORY_TASK: &str = "Stop after JS-owned repair/investigation attempts because inventory is still malformed or contains unresolved/non-canonical dependencies. Include repair_attempts with call IDs, issue kinds, canonical task IDs, files read, commands run, artifacts checked, redacted env keys checked, evidence refs, and exact reasons the workflow cannot safely continue.";

pub const BLOCKED_EMPTY_INVENTORY_TASK: &str = "Stop because the inventory is empty. Accept this only if every canonical task has concrete accepted/noop evidence; otherwise report the missing inventory evidence.";

pub const DEADLOCK_GRAPH_REPAIR_TASK: &str = "Repair a dependency deadlock before terminal stop. Split grouped items by dependency readiness, add verified_noop prerequisite items with concrete proof refs, or return concrete unrecoverable graph evidence with files read, commands/artifacts checked, and canonical task IDs.";

pub const BLOCKED_DEPENDENCY_DEADLOCK_TASK: &str = "Stop because no remaining implementation items are dependency-ready after bounded JS-owned dependency graph repair. Report exhausted graph repair evidence and next valid restart/remediation choices.";

pub const NOOP_PROOF_VERIFICATION_TASK: &str = "Verify the assigned dependency-ready no-op proof against every exact host-pinned task_acceptance_criteria entry from the authoritative TASK file. Do not modify files. Enumerate every criterion in acceptance_criteria_results with the exact criterion text, status, and concrete evidence_refs. An item with a required-universe deliverable contract cannot be noop when any declared identity is missing, any declared substantive predicate fails, or the deliverable records a gap. Return item_id, canonical_task_ids, status accepted/noop only when every criterion is explicitly satisfied with concrete proof refs, artifacts checked, commands if any, and no residual gaps. Reject stale, circular, summary-only, or accepted-report-only proof. Every deliverable contract carries a host-stamped artifact_status (resolved_path, exists, bytes, root) computed against projectArtifactRoot and targetRepositoryRoot at run start; treat it as the authoritative existence signal for declared artifacts. Never conclude a declared artifact is absent from globs or directory listings inside your checkout: agent worktrees are git checkouts and cannot contain gitignored or project-root files.";

pub const NOOP_EVIDENCE_REPAIR_TASK: &str = "Repair failed dependency-ready no-op proof into re-verifiable no-op items or concrete proof gaps. Preserve canonical task IDs and return items only when further verification can be safely attempted.";

pub const NOOP_PROOF_REVERIFICATION_TASK: &str = "Re-verify repaired dependency-ready no-op proof against every exact host-pinned task_acceptance_criteria entry. Do not modify files. Return acceptance_criteria_results with one exact criterion, status, and concrete evidence_refs per criterion. Return item_id, canonical_task_ids, accepted/noop only when every criterion is explicitly satisfied with concrete proof refs, artifacts checked, commands if any, and no residual gaps. Every deliverable contract carries a host-stamped artifact_status (resolved_path, exists, bytes, root) computed against projectArtifactRoot and targetRepositoryRoot at run start; treat it as the authoritative existence signal for declared artifacts. Never conclude a declared artifact is absent from globs or directory listings inside your checkout: agent worktrees are git checkouts and cannot contain gitignored or project-root files.";

pub const BLOCKED_NOOP_PROOF_FAILED_TASK: &str = "Stop only because dependency-ready no-op proof was refuted after bounded evidence repair and the task cannot be scheduled as implementation work, or it was already reclassified once and its normal implementation lifecycle owns the remaining failure. Report exact proof gaps and why no implementation route remains.";

pub const IMPLEMENTATION_WAVE_TASK: &str = "Repository source paths resolve against the item's target_repository_root and .archon/... project artifact paths against project_artifact_root; never prefix repository source with the artifact root. Implement only the assigned dependency-ready item. Every tool named in required_tools must appear in a command you actually executed and reported in commands_run: run the item's focused_verification commands verbatim rather than substituting your own file-search or inspection tools for them, because a declared tool exercised only through an equivalent is recorded as never exercised and the result is rejected. If a declared tool genuinely cannot run, execute it anyway and report the captured failure. An evidence entry's kind names what produced it: kind test is only for an executed test and, on an accepted or noop outcome, must be backed by a test-kind command with a succeeded status in commands_run. Record tool-exercise notes, file and size checks, greps, and audit inspections as kind inspection, never as kind test; a single test-kind evidence entry with no successful test command rejects the whole outcome, which is how an artifact-only task that runs no tests loses a correct result. For an item declaring a required-universe deliverable contract, consume its declared environment, use its declared live tools, and regenerate the deliverable so every declared identity and substantive predicate is satisfied. An empty or gap-only required universe is actionable work and cannot be accepted or noop; accepted/noop requires the generated contract verification plus redacted provider_env_proof for any declared keys. Return one structured outcome per item with item_id, canonical_task_ids, snake_case status, evidence, changed files, commands/tests, artifacts, and residual gaps. Use accepted or noop only with concrete task-linked proof.";

pub const BLOCKED_SILENT_IMPLEMENTATION_WAVE_TASK: &str = "Stop because the implementation wave produced no trace: no branch reported a landed patch, changed files, or artifacts, and no branch declared an idempotent no-op. Report each branch, its status, the exact reason it wrote nothing, and what would have to change for the wave to do work. Do not describe the wave as implemented.";

pub const REMEDIATION_INVENTORY_TASK: &str = "Create remediation items only for non-accepted/non-noop implementation outcomes from the current wave. Reuse target_files from the original readyImplementationItems/source item; do not target workflow.js, branch JSON, task docs, or artifacts unless the source item explicitly owned them. Each remediation item must include item_id, source_item_id, canonical_task_ids, target_files, failure_status, failure_evidence, required_fix, verification_requirements, dependency_ids, focused verification, and artifact requirements. Use target_files only for repo-owned implementation file paths; artifact-only remediation must set target_files to [] and put concrete project artifact paths in artifact_requirements. Never place instructions, evidence guidance, or prose in target_files or artifact_requirements; prose evidence belongs in expected_evidence and fix instructions belong in required_fix.";

pub const REMEDIATION_EMPTY_INVENTORY_REPAIR_TASK: &str = "Repair an empty or malformed remediation inventory into actionable remediation items for the non-accepted implementation outcomes, preserving canonical task IDs, target files, verification, and artifact requirements, or return concrete evidence that no safe remediation can be inferred.";

pub const BLOCKED_MALFORMED_REMEDIATION_TASK: &str = "Stop because implementation produced non-accepted outcomes but bounded JS-owned remediation inventory repair remained empty or malformed. Report exact unresolved outcomes and contract issues.";

pub const REMEDIATION_WAVE_TASK: &str = "Repository source paths resolve against the item's target_repository_root and .archon/... project artifact paths against project_artifact_root; never prefix repository source with the artifact root. Remediate only the assigned unresolved item. Every tool named in required_tools must appear in a command you actually executed and reported in commands_run: run the item's focused_verification commands verbatim rather than substituting your own file-search or inspection tools for them, because a declared tool exercised only through an equivalent is recorded as never exercised and the result is rejected. If a declared tool genuinely cannot run, execute it anyway and report the captured failure. Return item_id, canonical_task_ids, snake_case status, concrete evidence, changed files, commands/tests, artifacts, and residual gaps.";

pub const REMEDIATION_OUTCOME_REPAIR_TASK: &str = "Repair unresolved remediation outcomes into a follow-up remediation inventory, preserving original source-owned target files, canonical task IDs, failure_status, failure_evidence, required_fix, verification, and artifact requirements. For a size/format/complexity contract failure, split code into an owned module or retry the minimal correction; every source file must remain below 500 lines. Do not infer target files from workflow scripts, branch result JSON, or artifact paths. Use target_files only for repo-owned implementation file paths; artifact-only remediation must set target_files to [] and put concrete project artifact paths in artifact_requirements. Never place instructions, evidence guidance, or prose in target_files or artifact_requirements; prose evidence belongs in expected_evidence and fix instructions belong in required_fix.";

pub const REMEDIATION_OUTCOME_SHAPE_REPAIR_TASK: &str = "Repair only the shape of an outcome-repair inventory. Return one direct canonical items array that accounts for every supplied unresolved outcome. Preserve source item IDs, canonical task IDs, target ownership, failure status/evidence, required fixes, verification, artifact requirements, and classifications verbatim. Do not invent work, drop outcomes, reclassify failures, or claim completion.";

pub const FOLLOWUP_REMEDIATION_WAVE_TASK: &str = "Repository source paths resolve against the item's target_repository_root and .archon/... project artifact paths against project_artifact_root; never prefix repository source with the artifact root. Run follow-up remediation only for the assigned unresolved item. Every tool named in required_tools must appear in a command you actually executed and reported in commands_run: run the item's focused_verification commands verbatim rather than substituting your own file-search or inspection tools for them, because a declared tool exercised only through an equivalent is recorded as never exercised and the result is rejected. If a declared tool genuinely cannot run, execute it anyway and report the captured failure. Return item_id, canonical_task_ids, snake_case status, concrete evidence, changed files, commands/tests, artifacts, and residual gaps.";

pub const OWNERSHIP_EXPANSION_INVENTORY_TASK: &str = "Review unresolved write-branch evidence that proposes explicit repo path ownership expansion. Return follow-up remediation items only when each added path is an exact repo-owned file needed for the same canonical task and supported by branch evidence. Preserve existing target_files, append only justified explicit files, keep dependency_ids canonical, include focused_verification and artifact_requirements, and do not broaden by directory, language, framework, glob, or project artifact path.";

pub const OWNERSHIP_EXPANSION_WAVE_TASK: &str = "Run follow-up remediation only for the assigned unresolved item after JS-owned explicit ownership expansion. Return item_id, canonical_task_ids, snake_case status, concrete evidence, changed files, commands/tests, artifacts, and residual gaps.";

pub const BLOCKED_REMEDIATION_UNRESOLVED_TASK: &str = "Stop because bounded JS-owned remediation attempts left unresolved implementation outcomes. Report exact remaining gaps and next valid restart/remediation choices.";

pub const VERIFICATION_PLAN_TASK: &str = "Plan focused verification for newly implemented or remediated canonical task IDs before dependents can unblock. Cover every acceptance criterion. The taskUniverse pins each canonical task's authoritative acceptance_criteria; the plan you return decides what the wave will ever prove, and nothing downstream re-derives it. Every criterion of every candidate task must be claimed by at least one item in covered_acceptance_criteria, quoting the criterion text exactly as the taskUniverse states it. Criteria may be split across items, one running the command and another inspecting the artifact. A criterion describing a runtime outcome — data written, a count reached, a status reported, a service answering — is not covered by a check that the code compiles or that a file exists; plan the command that produces the outcome and the check that reads it back. Return one verification item per exact command/check whenever possible. Each item must include item_id, canonical_task_ids, focused_verification, expected_evidence, optional artifact_requirements, source_item_id, and required_tools when the task declares project tooling. Diff-scope checks must use the source branch write_coordination_scope and enforce observed changed/created/deleted files as a subset of declared_target_files; declared files need not change and empty observed files are valid for idempotent_noop. Never use git status of the shared repository tree or reverse the subset. Artifact checks must enumerate exact artifact fields or paths from the task specification; never invent an artifact field that the task does not require. For normalization checks, read manifest.normalized_path and verify that referenced target exists and parses; never require a literal normalized/ child directory unless the task or manifest explicitly declares one. Required-universe verification must execute the generated deliverable contract exactly: every declared identity must exist, every declared field/count/status/internal-consistency predicate must pass, declared payload substance and cross-identity checks must pass, and declared gaps must be empty. Require redacted run-scoped provider proof for declared provider keys. A provider with no declared keys satisfies the environment predicate with checked_keys=[] plus an explicit no-keys-required note. When a task contract explicitly permits success OR unavailable, a structured fail-closed unavailable result is a valid outcome and must not be converted into an implementation failure. Raw external payloads must not be required to contain canonical task IDs unless the TASK explicitly requires that field on that exact artifact. Never fail on vague requirements such as all required artifact path fields or all expected artifacts unless the item lists them explicitly. Check project artifacts relative to projectArtifactRoot when present, and accepted predecessor proof outcomes under workflow_branch_evidence_root before declaring them missing. Repository source files resolve relative to targetRepositoryRoot. Before emitting a cargo test command, derive the exact package name with cargo metadata and grep-verify every requested test symbol in repository source; never assume a binary name is also a package name. Never set CARGO_TARGET_DIR in an agent command; the host owns the shared target directory. When provider/API credentials matter, include provider_env_requirements with exact env key names and require redacted provider_env_proof; never include values. Evidence is accepted when at least one intended target passes and no intended target fails; duplicate cargo workspace/lib/bin harness pass sections are valid as one canonical pass.";

pub const VERIFICATION_PLAN_REPAIR_TASK: &str = "Repair an empty or malformed focused verification plan into concrete verification items, preferably one item per exact command/check, with item_id, canonical_task_ids, focused_verification, expected_evidence, optional artifact_requirements, and source_item_id. The input carries uncoveredAcceptanceCriteria: every entry is a criterion the current plan never promised to check, and the repaired plan must claim each one in covered_acceptance_criteria with the criterion text quoted exactly. A criterion describing a runtime outcome is not covered by a compile or file-existence check. Artifact checks must enumerate exact fields or paths; do not use vague all required artifact path fields or all expected artifacts wording. Check project artifacts relative to projectArtifactRoot when present. Include provider_env_requirements and redacted provider_env_proof requirements for provider-sensitive checks, or return concrete evidence that verification cannot be inferred safely.";

pub const BLOCKED_EMPTY_VERIFICATION_TASK: &str = "Stop because bounded JS-owned repair could not produce a focused verification plan for newly implemented work.";

pub const VERIFICATION_WAVE_TASK: &str = "Run focused verification only. The input names target_repository_root, project_artifact_root, and workflow_branch_evidence_root explicitly; repository source paths resolve against target_repository_root, .archon/... project artifact paths resolve against project_artifact_root, and accepted predecessor proof outcomes resolve under workflow_branch_evidence_root. Search both artifact roots before declaring proof absent. For normalization checks, follow manifest.normalized_path and validate the referenced file; never demand a literal normalized/ child directory unless declared. For diff-scope checks, require observed changed/created/deleted files to be a subset of write_coordination_scope declared_target_files; declared files need not change and an empty observed set is valid for idempotent_noop. Never reverse this subset or use shared-tree git status as branch ownership evidence. A declared deliverable passes only when its generated contract verification succeeds for every declared identity, field, count, internal-consistency, payload-substance, cross-identity, registry, and gap predicate. Keyless providers pass the environment predicate with checked_keys=[] and an explicit no-keys-required note. An explicit success OR unavailable contract accepts structured fail-closed unavailable evidence. Never set CARGO_TARGET_DIR; the host owns the shared target directory. Derive Cargo package names from cargo metadata and never substitute a binary name. Return structured status, item_id, canonical_task_ids, focused_verification executed, commands run with exit_code and output_summary, matched test/check names, pass/fail count, artifacts checked, source_item_id, verification_failure_class when failed, and residual gaps. Whenever a test command fails, return pass_fail_count with intended_target_passed and intended_target_failed plus matched_test_check_names.failed as an array; flat pass_count/fail_count or an unstructured matched-test array is insufficient. Accept duplicate cargo workspace/lib/bin harness pass sections as one canonical pass when at least one intended target passes and no intended target fails. Do not modify files.";

pub const VERIFICATION_FAILURE_TRIAGE_TASK: &str = "Classify failed focused verification outcomes. Return actionable implementation failures in implementation_failures as items requiring write remediation, retryable verification-shape issues in retry_items only for checks that actually require rerun, and accepted sibling-covered failures in superseded_items. Before classifying a missing artifact field as actionable, prove the TASK contract requires that field on that exact artifact. Raw provider payloads are not implicitly Archon-task-tagged: a verifier demanding a canonical task ID on raw/request.json, raw/response.*, raw/headers.redacted.json, or raw/provider-notes.md is verification over-reach unless the TASK explicitly requires it, and must be corrected in retry_items or superseded_items rather than implementation_failures. A stale-filter or zero-match test failure MUST be a retry_item with repository-search-verified corrected exact test names; such failures are never superseded_items. implementation_failures, retry_items, and superseded_items must include item_id, source_item_id, canonical_task_ids, source_residual_gap_ids, failed_predicate, focused_verification or recommended_retry, and expected_evidence. Preserve every source residual gap ID and its failed predicate; dropping either is a contract error. Allowed classifications include actionable_implementation_failure, retryable_verification_shape_issue, retry_resolved_by_sibling_evidence, and retry_resolved_verification_execution_issue. Return terminal external/runtime/safety blockers with concrete evidence. Never emit a terminal_blocker for an issue also classified into retry_items, superseded_items, or implementation_failures in the same triage. Retryable execution/build failures escalate to terminal only after host evidence shows the same preserved gap IDs reproduced across at least two retry generations. Do not mark tasks complete.";

pub const VERIFICATION_TRIAGE_SHAPE_REPAIR_TASK: &str = "Repair the supplied triage output SHAPE only. Every supplied non-accepted verification outcome must be accounted for in exactly one TOP-LEVEL array of the returned data object: retry_items, implementation_failures, superseded_items, or terminal_blockers — direct children of data, never nested under items, triage, routes, or any other container. Move any route entries found in nested containers to the top-level arrays. Preserve the original classifications, item_id, source_item_id, canonical_task_ids, source_residual_gap_ids, and failed_predicate values unchanged; do not invent, drop, or reclassify items, and do not mark tasks complete.";

/// Sent only after the host has REJECTED a shape repair for dropping protected
/// fields. The repair prompt already states the preservation contract, so
/// restating it changes nothing; this one names the exact fields the reducer
/// dropped, on the exact items, so the correction is mechanical.
pub const VERIFICATION_TRIAGE_PRESERVATION_RETRY_TASK: &str = "Your previous shape repair was REJECTED by the host because it mutated or dropped protected fields. The supplied violations list names every offending field and the item it belongs to. Re-emit the repaired triage with the SAME top-level route arrays and the SAME set of items, but copy each named protected field VERBATIM from the pre-repair triage supplied alongside the violations. Protected fields are source_residual_gap_ids, failed_predicate, classification, canonical_task_ids, source_item_id, failure_status, and failure_evidence. Do not reclassify, drop, invent, merge, or renumber items, do not move items between route arrays, and do not mark tasks complete. Change nothing except restoring the protected field values.";

pub const VERIFICATION_FAILURE_RETRIAGE_TASK: &str = "Re-triage failed focused verification outcomes once because host-side invariant enforcement rejected the proposed supersede as unprovable. Emit corrected retry_items for every stale-filter or zero-match test failure, using repository-search-verified corrected exact test names from the supplied failure evidence. Preserve source_residual_gap_ids and failed_predicate. Do not return those failures in superseded_items, implementation_failures, or terminal_blockers. Do not mark tasks complete.";

pub const VERIFICATION_REMEDIATION_INVENTORY_TASK: &str = "Create write-capable remediation items only for actionable implementation failures proven by focused verification. Every item must include item_id, source_item_id, canonical_task_ids, dependency_ids using canonical task IDs only, target_files from the original implementation item ownership, failure_status, failure_evidence, required_fix, focused_verification, and artifact_requirements.";

pub const VERIFICATION_REMEDIATION_WAVE_TASK: &str = "Fix only the assigned focused-verification failure. Use the original implementation item's ownership. For provider-sensitive remediation, consume the host-injected run-scoped provider environment and its redacted proof; do not independently source shell profiles. Required-universe remediation must use the task's declared live tools and regenerate artifacts until every declared identity and substantive predicate passes; an empty or gap-only artifact is not a valid noop. Reject an unavailable-provider conclusion unless redacted provider_env_proof names the declared checked keys and presence states, never credential values. Keyless providers use checked_keys=[] with an explicit no-keys-required note. An explicit success OR unavailable contract accepts structured fail-closed unavailable evidence. Return item_id, canonical_task_ids, snake_case status, concrete evidence, changed files, commands/tests, artifacts, and residual gaps.";

pub const POST_REMEDIATION_VERIFICATION_PLAN_TASK: &str = "Plan focused verification after write remediation. Cover every acceptance criterion. The taskUniverse pins each canonical task's authoritative acceptance_criteria; the plan you return decides what the wave will ever prove, and nothing downstream re-derives it. Every criterion of every candidate task must be claimed by at least one item in covered_acceptance_criteria, quoting the criterion text exactly as the taskUniverse states it. Criteria may be split across items, one running the command and another inspecting the artifact. A criterion describing a runtime outcome — data written, a count reached, a status reported, a service answering — is not covered by a check that the code compiles or that a file exists; plan the command that produces the outcome and the check that reads it back. Return one item per exact command/check with item_id, canonical_task_ids, focused_verification, expected_evidence, optional artifact_requirements, and source_item_id. Diff-scope checks must require observed changed/created/deleted files to be a subset of write_coordination_scope declared_target_files; declared files need not change and empty observed writes are valid for idempotent_noop. Never reverse the subset or use shared-tree git status. Required-universe verification must execute the generated contract and fail on any missing identity, failed declared predicate, insufficient payload substance, cross-identity collision, or declared gap. Include provider_env_requirements for provider-sensitive checks and require redacted provider_env_proof only.";

pub const POST_REMEDIATION_VERIFICATION_PLAN_REPAIR_TASK: &str = "Repair malformed post-remediation verification output into canonical focused verification items with item_id, canonical_task_ids, focused_verification, expected_evidence or artifact_requirements, and source_item_id.";

pub const POST_REMEDIATION_VERIFICATION_WAVE_TASK: &str = "Run focused post-remediation verification only. The input names target_repository_root and project_artifact_root explicitly; resolve .archon/... paths against project_artifact_root, never the repository working directory. For diff-scope checks, require observed changed/created/deleted files to be a subset of write_coordination_scope declared_target_files; declared files need not change and empty observed writes are valid for idempotent_noop. Never reverse the subset or use shared-tree git status. Return structured status, item_id, canonical_task_ids, commands run with exit_code and output_summary, matched checks, pass/fail count, artifacts checked, source_item_id, verification_failure_class when failed, and residual gaps. Whenever a test command fails, return pass_fail_count with intended_target_passed and intended_target_failed plus matched_test_check_names.failed as an array. Do not modify files.";

pub const VERIFICATION_REPAIR_PLAN_TASK: &str = "Repair failed focused verification shape into a concrete retry plan only when the issue is missing/malformed verification evidence, target selection, or retryable command shape. Every retry item must preserve source_residual_gap_ids and failed_predicate from the failed outcome and verify that exact predicate. If a predicate is false about the execution environment, return route: predicate_unsatisfiable_as_written with re_authored_items grounded in runtime-provided evidence and preserving the original source gap ID; do not blindly retry it. Diff-scope checks must use write_coordination_scope, never shared-tree git status. For a genuine missing concrete artifact or product-code failure, return route: write_remediation with the affected source outcome IDs instead of another retry item. A consistently reproduced product or test failure requires route: write_remediation, never another verification retry. Do not use verification repair for product-code or artifact-contract failures; those require write remediation.";

pub const VERIFICATION_REPAIR_SHAPE_REPAIR_TASK: &str = "Repair malformed focused verification retry output into canonical items. Return items with item_id, canonical_task_ids, focused_verification, expected_evidence or artifact_requirements, source_item_id, and provider_env_requirements when provider credentials are required. The host stamps source_residual_gap_ids and failed_predicate from the matched failed outcome; do not invent or replace gap identity. Artifact checks must enumerate exact fields or paths and must not use vague all required artifact path fields or all expected artifacts wording. Project artifact checks must name projectArtifactRoot-relative paths when possible.";

pub const RETRY_VERIFICATION_WAVE_TASK: &str = "Run repaired focused verification only. The input names target_repository_root, project_artifact_root, and workflow_branch_evidence_root explicitly; repository source paths resolve against target_repository_root, .archon/... project artifact paths resolve against project_artifact_root, and accepted predecessor proof outcomes resolve under workflow_branch_evidence_root. Search both artifact roots before declaring proof absent. Dataset normalization checks follow manifest.normalized_path and never require an undeclared literal normalized/ directory. Diff-scope retries must validate write_coordination_scope and never shared-tree git status. Return structured status, item_id, canonical_task_ids, focused_verification executed, commands run with exit_code and output_summary, matched test/check names, pass/fail count, artifacts checked, source_item_id, verification_failure_class when failed, and residual gaps. Whenever a test command fails, return pass_fail_count with intended_target_passed and intended_target_failed plus matched_test_check_names.failed as an array. Do not modify files.";

pub const BLOCKED_VERIFICATION_FAILED_TASK: &str = "Stop because bounded JS-owned verification triage, verification repair, and write remediation did not produce accepted/noop evidence. Report exact commands/results, remediation attempts, and unresolved gaps.";

pub const WAVE_COMPLETION_REMEDIATION_TASK: &str = "Close the completion gaps that stopped this dependency-ready wave from finishing. You are write-capable: fix the work itself rather than restating the gap. Add the missing tests, implement the missing behaviour, and correct claims that do not match what is on disk, then run the item's focused_verification and return the captured results. Every tool named in required_tools must appear in a command you actually executed and reported in commands_run. Return one structured outcome per item with item_id, canonical_task_ids, snake_case status, evidence, changed files, commands/tests, artifacts, and residual gaps. Use accepted only when the acceptance criteria are genuinely met with concrete task-linked proof; report an honest blocked status with captured evidence when the work cannot be completed.";

pub const WAVE_COMPLETION_EVIDENCE_REPAIR_TASK: &str = "Repair a dependency-ready wave that produced no newly completed canonical task IDs. Return concrete completion evidence to re-check, or exact evidence-backed gaps that prevent safe unblocking.";

pub const BLOCKED_NO_COMPLETION_TASK: &str = "Stop because the dependency-ready wave produced no new verified accepted/noop canonical task IDs after JS-owned completion evidence repair.";

pub const BLOCKED_LOOP_EXHAUSTION_TASK: &str = "Stop because the bounded dependency loop ended with unresolved implementation items. Report unresolved task IDs and dependency evidence.";

pub const ARTIFACT_INVENTORY_TASK: &str = "List every task-declared generated artifact and final evidence artifact. Include only real paths that should exist.";

pub const SAVE_ARTIFACT_INVENTORY_TASK: &str =
    "Persist the artifact inventory and evidence references for final acceptance.";

/// Per-task adversarial review (PARALLEL, one branch per task).
///
/// Deliberately never asks the reviewer to record which task a finding belongs
/// to: the branch it runs in reviews exactly one task, and the host stamps that
/// branch id, so attribution is recovered structurally. Asking would only
/// create a field the model can forget.
pub const PER_TASK_ADVERSARIAL_REVIEW_TASK: &str = "You did NOT do this work — be suspicious of it. Run read-only adversarial review of ONE task only: the task named by task_id in your item. You are shown that task's acceptance_criteria, its declared adversarial_review_notes, its artifact_requirements, and its own implementation/verification evidence in task_evidence. Try to FALSIFY the claim that this task is genuinely done. Check every entry in adversarial_review_notes explicitly — those are the task author's own falsification hypotheses and each one must be answered with concrete evidence. Check every acceptance criterion against the evidence rather than against the summary that claims it. Verify declared artifact paths actually exist and contain what the criterion requires; an accepted report is not evidence. Do not review, comment on, or speculate about any other task — you cannot see them and must not infer them. Do not modify files. Return data.findings as compact structured findings, at most 25, each with a claim, the counter_evidence that supports it, and a severity. Return an empty findings array only when you could not falsify anything. There is a third verdict beyond pass and gaps: if the task AS WRITTEN cannot or should not be done — the acceptance criteria contradict the code, the artefact it demands cannot exist, the change would break a stated invariant — say so instead of inventing work that would pass. Return that finding with verdict set to the exact string assignment_invalid, canonical_task_ids naming the task, a reason of at least one full sentence explaining why the assignment is wrong rather than merely hard, and evidence containing at least one file:line reference to the code that establishes it. A verdict missing any of those is refused and handled as an ordinary finding. Never use assignment_invalid for work you could not complete.";

pub const CROSS_CUTTING_REVIEW_TASK: &str = "Every task has ALREADY been adversarially reviewed on its own, one reviewer per task, and those findings are preserved verbatim by the host — you are not being asked for them and restating one contributes nothing. Review ONLY what a single-task reviewer structurally could not see: contradictions BETWEEN tasks (two tasks whose evidence cannot both be true, an interface one task produces and another consumes differently), global invariants that hold only across the whole deliverable, dependency-order violations in taskUniverse, and PRD-level acceptance that no individual task owns. You are given the task universe and a digest of the per-task findings; use the digest only to spot contradictions across findings. Return issue items only for genuinely cross-cutting concerns, each naming the canonical task IDs it spans. Return accepted with no items when no cross-cutting concern remains. Do not modify files.";

pub const CROSS_CUTTING_RE_REVIEW_TASK: &str = "Re-run cross-task review after remediation. Per-task review has already re-run for every remediated task and its findings are preserved by the host. Return issue items only for contradictions BETWEEN tasks, global invariants, dependency-order violations, or PRD-level acceptance that no individual task owns, each naming the canonical task IDs it spans. Do not restate per-task findings. Return accepted with no items when no cross-cutting concern remains. Do not modify files.";

pub const REVIEW_REMEDIATION_INVENTORY_TASK: &str = "Turn adversarial review issues into dependency-safe remediation items. Every item must include item_id, canonical_task_ids using taskUniverse canonical task IDs only, dependency_ids using canonical task IDs only, source_item_id, failure_status, failure_evidence, required_fix, target_files, focused_verification, and artifact_requirements. Use target_files only for repo-owned implementation files; artifact-only remediation must set target_files to [] and put concrete project artifact paths in artifact_requirements. Prose evidence expectations belong in expected_evidence, not artifact_requirements. Do not invent remediation IDs as canonical_task_ids.";

pub const REVIEW_REMEDIATION_INVENTORY_REPAIR_TASK: &str = "Repair review remediation inventory shape before write fanout. Return full replacement items only. Use canonical taskUniverse IDs in canonical_task_ids/dependency_ids. Include target_files only for repo-owned source edits; use [] for artifact-only remediation with concrete artifact paths in artifact_requirements. Preserve failure context, required_fix, focused_verification, and artifact requirements. Put prose evidence expectations in expected_evidence. Do not invent synthetic canonical task IDs.";

pub const BLOCKED_EMPTY_REVIEW_REMEDIATION_TASK: &str = "Stop because adversarial review found issues but review remediation inventory is still empty or malformed after JS-owned repair.";

pub const REVIEW_REMEDIATION_WAVE_TASK: &str = "Fix only the assigned adversarial review issue. Return canonical task IDs, status, concrete evidence, commands/tests, artifacts, and residual gaps. Place evidence or placeholder outputs under the workflow run artifact directory, not inside canonical product artifact trees unless the source item explicitly owns that concrete artifact path.";

